from fractions import Fraction

R = [
    Fraction(7, 3),
    Fraction(11, 4),
    Fraction(2024, 5),
    Fraction(109, 11),
    Fraction(3, 71),
    Fraction(5, 204)
]

pairs_found = []

for i in range(len(R)):
    for j in range(i + 1, len(R)):
        r = R[i]
        r_prime = R[j]

        # 1. Check r + r' = 0 (i.e., r' = -r)
        if r + r_prime == 0:
            pairs_found.append((r, r_prime, "r+r'=0"))

        # 2. Check r + r' = 1 (i.e., r' = 1 - r)
        elif r + r_prime == 1:
            pairs_found.append((r, r_prime, "r+r'=1"))

        # 3. Check r * r' = 1 (i.e., r' = 1/r)
        elif r * r_prime == 1:
            pairs_found.append((r, r_prime, "rr'=1"))

if pairs_found:
    for r, r_prime, condition in pairs_found:
        print(f"Pair ({r}, {r_prime}) satisfies {condition}")
else:
    print("No pairs satisfy the constraints.")

from fractions import Fraction

def get_neighbors(r):
    neighbors = set()
    # r + r' = 0 => r' = -r
    r1 = -r
    if r1 != r:
        neighbors.add(r1)
    # r + r' = 1 => r' = 1-r
    r2 = 1 - r
    if r2 != r:
        neighbors.add(r2)
    # rr' = 1 => r' = 1/r
    if r != 0:
        r3 = 1 / r
        if r3 != r:
            neighbors.add(r3)
    return neighbors

def get_orbit(start_r):
    orbit = {start_r}
    queue = [start_r]
    while queue:
        curr = queue.pop(0)
        for neighbor in get_neighbors(curr):
            if neighbor not in orbit:
                orbit.add(neighbor)
                queue.append(neighbor)
    return orbit

def get_distance(start_r, target_r):
    if start_r == target_r:
        return 0
    queue = [(start_r, 0)]
    visited = {start_r}
    while queue:
        curr, dist = queue.pop(0)
        for neighbor in get_neighbors(curr):
            if neighbor == target_r:
                return dist + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return None

